insert into public.deals (external_key, date, date_text, kind, asset_class, sport, target, target_kind, target_country, target_team_id, target_company_id, investor, investor_type, investor_company_id, investor_id, seller, stake_pct, amount, currency, valuation, valuation_currency, headline, summary, source_name, source_url, source)
  values ('deal:crystal-palace-football-club:josh-harris-and-david-blitzer:december-2015', null, 'December 2015', 'minority_investment', 'sports', 'football', 'Crystal Palace Football Club', 'club', 'England', (select id from public.sports_teams where external_key = 'premier-league--crystal-palace'), null, 'Josh Harris and David Blitzer', 'individual', (select id from public.companies where lower(name) = lower('Josh Harris and David Blitzer') limit 1), (select id from public.sports_investors where lower(name) = lower('Josh Harris and David Blitzer') limit 1), null, 36, 50000000, 'GBP', null, null, 'Harris and Blitzer take 18% each in Crystal Palace with £50m capital injection', 'Josh Harris (Apollo co-founder) and David Blitzer (Blackstone) each acquired 18% of Crystal Palace, injecting £50m of capital and forming a general partnership with chairman Steve Parish. The investors also committed a further £50m towards stadium development.', 'SportBusiness', 'https://www.sportbusiness.com/news/crystal-palace-confirms-investment-deal-with-american-businessmen/', 'web_research')
